function symptom(msg) { console.error("FAIL: " + msg); process.exit(1); }
function broken(msg) { console.error("ERROR: " + msg); process.exit(2); }
const z = require("zod");
const inner = z.string().meta({ id: "Inner" });
const out = z.toJSONSchema(z.object({ a: inner, b: inner }));
const def = out && out.$defs && out.$defs.Inner;
if (!def) broken("z.toJSONSchema did not put Inner into $defs: " + JSON.stringify(out));
if (def.type !== "string") broken("unexpected $defs.Inner: " + JSON.stringify(def));
if (def.id === "Inner") symptom("z.toJSONSchema keeps id in the $defs entry");
if ("id" in def) broken("unexpected id in $defs.Inner: " + JSON.stringify(def));
console.log("OK: z.toJSONSchema $defs entry has no id: " + JSON.stringify(def));

